<?php $pageTitle='Evaluaciones';$pageSubtitle='Presenta tus evaluaciones y consulta tus resultados.';require __DIR__.'/../partials/header.php'; ?><div class="grid"><?php foreach($evaluaciones as $e): ?><div class="card"><h3><?=htmlspecialchars($e['titulo_evaluacion'])?></h3><p><?=htmlspecialchars($e['titulo_curso'])?></p><span class="badge <?=($e['calificacion']!==null?'':'gray')?>"><?=($e['calificacion']!==null?'Realizada':'Pendiente')?></span><?php if($e['calificacion']!==null): ?><p>Calificación: <strong><?=$e['calificacion']?> / 5</strong></p><?php endif; ?><div class="actions"><a class="btn btn-primary" href="index.php?route=evaluacion&id=<?=$e['id_evaluacion']?>"><?=($e['calificacion']!==null?'Ver resultado':'Presentar')?></a></div></div><?php endforeach; ?><?php if(!$evaluaciones): ?><div class="empty">No tienes evaluaciones disponibles.</div><?php endif; ?></div><?php require __DIR__.'/../partials/footer.php'; ?>
